import cryptography.hazmat.bindings._rust as r

class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        associated_data = problem["associated_data"]

        # This is the fastest legitimate way I've found so far
        aesgcm = r.openssl.aead.AESGCM(key)
        res = aesgcm.encrypt(nonce, plaintext, associated_data)

        return {"ciphertext": res[:-16], "tag": res[-16:]}
